<template>
  <a-drawer :open="open" :title="health ? `${health.project_code} · ${health.project_name}` : '项目健康详情'" placement="right" :width="'min(1180px, 100vw)'" :destroyOnClose="true" @close="$emit('close')">
    <a-spin v-if="loading" size="large" style="display:block;margin:100px auto" />
    <a-alert v-else-if="error" type="error" :message="error" show-icon />
    <template v-else-if="health">
      <section class="health-hero">
        <div class="health-score" :class="`health-${health.summary.health_level}`"><strong>{{ health.summary.health_score }}</strong><span>/100</span><small>项目健康评分</small></div>
        <div class="health-verdict"><div class="health-verdict-label" :class="`health-text-${health.summary.health_level}`">{{ deliveryLabel }}</div><div class="health-verdict-detail">预计 {{ formatDate(health.summary.predicted_end) }}，结题日期 {{ formatDate(health.summary.due_date) }}</div><div class="health-verdict-detail">{{ scheduleLabel }} · 已完成 {{ health.summary.task_counts.completed || 0 }} / {{ health.summary.task_counts.total || 0 }} 项任务</div></div>
        <div class="health-metrics"><div><strong>{{ health.summary.task_counts.delayed || 0 }}</strong><span>延期</span></div><div><strong>{{ health.summary.task_counts.blocked || 0 }}</strong><span>阻塞</span></div><div><strong>{{ health.summary.task_counts.pending || 0 }}</strong><span>待完成</span></div></div>
      </section>
      <section class="health-section health-panel"><header><div><h3>项目任务进度</h3><span class="health-muted">项目安排 · 计划排程与实际执行结果</span></div></header><ProjectArrangement :items="health.arrangement_items" /></section>
    </template>
  </a-drawer>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import dayjs from 'dayjs'
import type { ProjectHealth } from '@/services/api'
import ProjectArrangement from './kanban/ProjectArrangement.vue'

const props = defineProps<{ open: boolean; loading: boolean; error: string; health: ProjectHealth | null }>()
defineEmits<{ close: [] }>()
const deliveryLabel = computed(() => ({ on_time: '预计按期交付', at_risk: '交付存在风险', overdue: '预计无法按期交付' }[props.health?.summary.delivery_status || 'at_risk']))
const scheduleLabel = computed(() => ({ not_scheduled: '尚未排程', scheduled: '已排程', dirty: '计划有变更待排程', executing: '正在执行', completed: '已完成' }[props.health?.summary.schedule_state || 'not_scheduled']))
function formatDate(value: string | null | undefined) { return value ? dayjs(value).format('MM-DD HH:mm') : '-' }
</script>

